    "direction_proposals": [
      {
        "label": "Combine local residues with cross-neighbor equations",
        "assignment": "For fixed distinct integer anchors a,b with ab+1 a rational square, combine the proved deep-denominator residue restriction with the simultaneous parametrization of common neighbors and all six cross-pair square conditions. Seek an all-height obstruction to four distinct nonzero pairwise adjacent common neighbors, or identify a precise obstruction to this route. Preserve zero square roots and exclude zero or repeated elements.",
        "kind": "proof",
        "target_claim": {
          "statement": "For every pair of distinct nonzero integer anchors a,b with ab+1 a rational square, there do not exist four distinct nonzero rational common neighbors that are pairwise adjacent under the condition xy+1 is a rational square.",
