            "a,b are distinct nonzero integers.",
            "ab+1 is a rational square."
          ],
          "quantifiers": [
            "Universally over all such anchor pairs and all rational common neighbors, with no height bound."
          ],
          "objective": "proof"
        }
      }
    ]
